"""Regenerate the material graph fixtures (W4; stdlib only, deterministic).

  Content/materials/graph/plain.swmaterial      a checker texture times a warm colour, roughness
                                                0.45, metallic 0.2: a standard material
  Content/materials/graph/forward.swmaterial    the same drawn by forward.swmatgraph, which works out
                                                exactly those values in nodes
  Content/materials/graph/forward.swmatgraph
  Content/materials/graph/lava.swmatgraph       scrolling noise glowing through cracks, a glow param
  Content/materials/graph/lava.swmaterial       a dark rock drawn by lava.swmatgraph
  Content/materials/graph/lava-plain.swmaterial lava.swmaterial without its graph (what
                                                material_graphs false must draw)
  Content/materials/graph/lava-cold.swmaterial  lava.swmaterial with graph_param glow 0 0 0
  Scenes/graph-{plain,forward,lava,lava-plain,lava-cold}.swscene
                                                a sphere and a cube in each material on a grey floor
Run it after changing it; the outputs are committed so tests don't need Python.
"""
from pathlib import Path

root = Path(__file__).resolve().parents[1]
HEADER = '# Generated by Tests/fixtures/graphics/Tools/material_graph.py; edit that, not this file.\n'
materials = root / 'Content/materials/graph'
materials.mkdir(parents=True, exist_ok=True)


def write(path, text):
    path.write_text(HEADER + text, newline='\n')


write(materials / 'plain.swmaterial',
      'swmaterial 1\nbase_color 0.9 0.6 0.4 1\nroughness 0.45\nmetallic 0.2\n'
      'texture base_color "textures/checker-fine.png"\n')
write(materials / 'forward.swmatgraph',
      '# The standard material plain.swmaterial, worked out in nodes: the same picture.\n'
      'swmatgraph 1\n'
      'node checker texture "textures/checker-fine.png"\n'
      'node warm constant 0.9 0.6 0.4\n'
      'node color multiply a=checker.rgb b=warm\n'
      'node rough constant 0.45\n'
      'node metal constant 0.2\n'
      'output base_color color\n'
      'output roughness rough\n'
      'output metallic metal\n')
write(materials / 'forward.swmaterial',
      'swmaterial 1\nbase_color 0.9 0.6 0.4 1\nroughness 0.45\nmetallic 0.2\n'
      'texture base_color "textures/checker-fine.png"\ngraph "materials/graph/forward.swmatgraph"\n')
write(materials / 'lava.swmatgraph',
      '# Glowing cracks: noise scrolling over the surface, sharpened, times a glow colour.\n'
      'swmatgraph 1\n'
      'node uv uv\n'
      'node scale constant 6\n'
      'node big multiply a=uv b=scale\n'
      'node speed constant 0.4 0.1\n'
      'node flow panner uv=big speed=speed\n'
      'node n noise uv=flow\n'
      'node cracks power a=n b=4\n'
      'node glow param glow 6 2 0.3\n'
      'node hot multiply a=glow b=cracks\n'
      'node rock constant 0.08 0.07 0.07\n'
      'node rough constant 0.9\n'
      'output base_color rock\n'
      'output emissive hot\n'
      'output roughness rough\n'
      '\n'
      '# layout uv 0 0\n'
      '# layout hot 400 120\n')
lava = 'swmaterial 1\nbase_color 0.3 0.3 0.32 1\nroughness 0.6\n'
write(materials / 'lava.swmaterial', lava + 'graph "materials/graph/lava.swmatgraph"\n')
write(materials / 'lava-plain.swmaterial', lava)
write(materials / 'lava-cold.swmaterial',
      'swmaterial 1\nparent "materials/graph/lava.swmaterial"\ngraph_param glow 0 0 0\n')

scene = '''shockwave_scene 2

entity "Environment"
  Environment
    sky_color 0.45 0.55 0.7 1
    ground_color 0.2 0.18 0.15 1
    ambient_intensity 0.6
    bloom_intensity 0
end

entity "Sun"
  Transform
    rotation -45 30 0
  Light
    type Directional
    color 1 0.96 0.9 1
    intensity 3
end

entity "Floor"
  Transform
    position 0 -0.6 0
    scale 8 0.2 6
  MeshRenderer
    mesh cube
    tint 0.5 0.5 0.5 1
end

entity "Sphere"
  Transform
    position -0.9 0.2 0
    scale 1.4 1.4 1.4
  MeshRenderer
    mesh sphere
    material "materials/graph/{material}.swmaterial"
end

entity "Box"
  Transform
    position 0.9 0.1 0
    rotation 0 30 0
    scale 1.1 1.1 1.1
  MeshRenderer
    mesh cube
    material "materials/graph/{material}.swmaterial"
end

entity "Main Camera"
  Transform
    position 0 1.4 3.6
    rotation -18 0 0
  Camera
    fov 55
    near_plane 0.1
    primary 1
end
'''
for name in ['plain', 'forward', 'lava', 'lava-plain', 'lava-cold']:
    write(root / f'Scenes/graph-{name}.swscene',
          f'# Material graphs (W4): a sphere and a box in materials/graph/{name}.swmaterial.\n' +
          scene.replace('{material}', name))
